function T(key){const dict=UI[uiLang]||UI.ru;return key.split('.').reduce((a,b)=>a&&a[b],dict)??key}
function goodName(id){return (GOOD_NAMES[id]&&GOOD_NAMES[id][uiLang])||findGood(id)?.name||id}
function nationName(name){return (NATION_NAMES[name]&&NATION_NAMES[name][uiLang])||name}
function portName(id){return (PORT_NAMES[id]&&PORT_NAMES[id][uiLang])||findPort(id)?.name||id}
function portDesc(id){return (PORT_DESCS[id]&&PORT_DESCS[id][uiLang])||findPort(id)?.desc||''}
function shipName(id){return SHIP_TEXT[id]?.[uiLang]?.name||SHIPS.find(s=>s.id===id)?.name||id}
function shipDesc(id){return SHIP_TEXT[id]?.[uiLang]?.desc||SHIPS.find(s=>s.id===id)?.desc||''}
function pirateName(id){return PIRATE_NAMES[id]?.[uiLang]||id}
function zoneName(id){return PIRATE_ZONES.find(z=>z.id===id)?.label?.[uiLang]||id}
function pirateClassName(id){return PIRATE_CLASSES.find(c=>c.id===id)?.name?.[uiLang]||id}
function zoneDangerLabel(d){return d<.26?ZONE_TEXT.dangerLow[uiLang]:d<.37?ZONE_TEXT.dangerMed[uiLang]:d<.44?ZONE_TEXT.dangerHigh[uiLang]:ZONE_TEXT.dangerHot[uiLang]}
function sampleRange(min,max,rand){return Math.round(min+(max-min)*rand())}
function routeExposure(a,b,zone){let inside=0,total=24;for(let i=0;i<=total;i++){const t=i/total,x=a.x+(b.x-a.x)*t,y=a.y+(b.y-a.y)*t;if(Math.hypot(x-zone.x,y-zone.y)<=zone.r)inside++}return inside/(total+1)}
function enemyBounty(enemy){const cls=PIRATE_CLASSES.find(c=>c.id===enemy.classId)||PIRATE_CLASSES[1];const avg=(cls.bounty[0]+cls.bounty[1])/2;return Math.round(avg+enemy.guns*12+enemy.crew*6)}

function money(n){return Math.round(n).toLocaleString(LOCALES[uiLang]||'ru-RU')+' '+(uiLang==='ru'?'кр.':'cr.')}
function dayUnit(n){return uiLang==='ru'?(n===1?'дн.':'дн.'):uiLang==='az'?'g.':'d.'}
function pct(n){return `${Math.round(n*100)}%`}
function setLanguage(lang){if(!['ru','en','az'].includes(lang))return;uiLang=lang;localStorage.setItem(LANG_KEY,lang);document.documentElement.lang=lang;render()}
function routePreview(targetId){const from=findPort(state.current),to=findPort(targetId),s=shipStats();const days=distanceDays(from,to,s);const seed=seedNumber(`${state.day}|${from.id}|${to.id}|${state.ship}|${state.reputation}|${state.winCount}`);let x=seed>>>0;const rnd=()=>((x=(x*1664525+1013904223)>>>0)/4294967296);const zoneHits=PIRATE_ZONES.map(z=>({zone:z,exposure:routeExposure(from,to,z)})).filter(z=>z.exposure>.08).sort((a,b)=>b.exposure*b.zone.danger-a.exposure*a.zone.danger);const totalExposure=zoneHits.reduce((sum,z)=>sum+z.exposure*z.zone.danger,0);const dominant=zoneHits[0]?.zone||null;const baseRisk=.035+days*.018;const risk=clamp(baseRisk+totalExposure*.82,dominant?.danger?dominant.danger*.55:0,.72);const dangerScore=(dominant?.danger||.18)+(zoneHits[0]?.exposure||0)*.35+days*.012+Math.max(0,state.reputation)*.002+Math.min(.08,state.winCount*.008);let classId='smuggler';if(dangerScore>.76)classId='dread';else if(dangerScore>.59)classId='hunter';else if(dangerScore>.44)classId='corsair';else if(dangerScore>.29)classId='raider';const cls=PIRATE_CLASSES.find(c=>c.id===classId)||PIRATE_CLASSES[1];const hull=sampleRange(cls.hull[0],cls.hull[1],rnd),crew=sampleRange(cls.crew[0],cls.crew[1],rnd),guns=sampleRange(cls.guns[0],cls.guns[1],rnd);const enemy={type:classId,name:pirateClassName(classId),classId,hull,maxHull:hull,crew,guns,power:cls.power,bountyRange:cls.bounty};const myPower=s.guns*2.35+state.hull*.74+state.crew*1.22+s.speed*18+state.upgrades.cannons*5+state.upgrades.hull*7;const enemyPower=guns*2.08+hull*.8+crew*1.15+cls.power*18+(dominant?.danger||.2)*20;const win=clamp(.16+(myPower-enemyPower)/220,.07,.94);const flee=clamp(.33+(s.speed-1)*.39+state.upgrades.sails*.045-(dominant?.danger||0)*.15,.11,.86);return{days,risk,enemy,myPower,enemyPower,win,flee,zoneHits,dominant,bounty:enemyBounty(enemy)}}
function powerLabel(diff){if(diff>75)return T('forecastWeak');if(diff>15)return T('forecastFair');if(diff>-45)return T('forecastStrong');return T('forecastDeadly')}
function combatWinEstimate(enemy){const s=shipStats();const myPower=s.guns*2.25+state.hull*.72+state.crew*1.25+s.speed*18+state.upgrades.cannons*5;const enemyPower=enemy.guns*2.1+enemy.hull*.78+enemy.crew*1.2;return clamp(.18+(myPower-enemyPower)/220,.08,.93)}
function combatFleeChance(round=1){const s=shipStats();return clamp(.36+(s.speed-1)*.36+state.upgrades.sails*.04-.015*round,.13,.82)}
function renderChrome(){document.title=T('title');document.documentElement.lang=uiLang;$('#brandTitle').textContent=T('brandTitle');$('#brandCaption').textContent=T('brandCaption');$('#helpBtn').textContent=T('help');$('#resetBtn').textContent=T('newGame');$('#mapEyebrow').textContent=T('mapEyebrow');$('#mapTitle').textContent=T('mapTitle');$('#legendHere').textContent=T('legendHere');$('#legendPorts').textContent=T('legendPorts');$('#portPickerLabel').textContent=T('portPickerLabel');$('#mapFootnote').textContent=T('mapFootnote');$('#tradeIntelEyebrow').textContent=T('tradeIntelEyebrow');$('#tradeIntelTitle').textContent=T('tradeIntelTitle');$('#tradeIntelFineprint').textContent=T('tradeIntelFineprint');$('#journalEyebrow').textContent=T('journalEyebrow');$('#journalTitle').textContent=T('journalTitle');$('#footerLeft').textContent=T('footerLeft');$('#footerRight').textContent=T('footerRight');document.querySelectorAll('.lang-btn').forEach(btn=>btn.classList.toggle('active',btn.dataset.lang===uiLang));const tabLabels=T('tabs');document.querySelector('[data-tab="trade"]').textContent=tabLabels.trade;document.querySelector('[data-tab="ship"]').textContent=tabLabels.ship;document.querySelector('[data-tab="estate"]').textContent=tabLabels.estate;document.querySelector('[data-tab="contracts"]').textContent=tabLabels.contracts;document.querySelector('[data-tab="journal"]').textContent=tabLabels.journal;document.querySelector('[data-tab="career"]').textContent=CT('tab')}

