function U(key){return MARKET_UX[uiLang]?.[key]||MARKET_UX.ru[key]||key}
function maxBuyable(gid){if(state.combat)return 0;const cost=price(state.current,gid,'buy');return Math.max(0,Math.min(stockGood(state.current,gid),Math.max(0,shipStats().capacity-loadQty()),Math.floor(state.gold/cost)))}
function remainingContract(job){return Math.max(0,job.qty-(state.cargo[job.good]||0))}
function contractForGood(gid){return state.activeContracts.filter(c=>c.good===gid&&state.day<=c.deadline).sort((a,b)=>a.deadline-b.deadline)[0]||null}
function opportunityDetails(){const origin=findPort(state.current),out=[];for(const g of GOODS){const buy=price(origin.id,g.id,'buy'),volume=maxBuyable(g.id);if(volume<1)continue;let best=null;for(const p of PORTS){if(p.id===origin.id)continue;const sell=price(p.id,g.id,'sell'),margin=sell-buy,days=distanceDays(origin,p,shipStats());if(margin<=0)continue;const gross=margin*volume;const score=gross/(days+1);if(!best||score>best.score)best={p,g,margin,buy,sell,days,volume,gross,score}}if(best)out.push(best)}return out.sort((a,b)=>b.score-a.score)}
function renderDockResources(){const s=shipStats(),used=loadQty(),free=Math.max(0,s.capacity-used),ratio=100*used/s.capacity;$('#dockResourceBar').innerHTML=`<div class="resource-chip"><span>${U('budget')}</span><strong class="gold">${money(state.gold)}</strong></div><div class="resource-chip hold-chip"><span>${U('hold')}</span><strong>${used}/${s.capacity} <small>· ${U('free')} ${free}</small></strong><div class="hold-meter"><i style="width:${ratio}%;background:${ratio>=90?'#e7a56b':'#7ed3bc'}"></i></div></div><div class="resource-chip"><span>${U('active')}</span><strong>${state.activeContracts.length}/2</strong></div>`}
function quickBuy(gid,mode,contractId){if(state.combat)return;const gidValid=GOODS.some(g=>g.id===gid);if(!gidValid)return;let amount=maxBuyable(gid);if(mode==='contract'){const c=state.activeContracts.find(x=>x.id===contractId&&x.good===gid);if(!c)return;amount=Math.min(amount,remainingContract(c))}if(amount<1){popup(U('noBuy'));return}state.selected=state.current;trade(gid,'buy',amount)}
function contractBuy(id){const job=state.activeContracts.find(x=>x.id===id);if(!job||state.combat)return;quickBuy(job.good,'contract',id)}
function showRoute(id){if(!findPort(id)||state.combat)return;state.selected=id;save();render();document.querySelector('.dock-top')?.scrollIntoView({behavior:'smooth',block:'start'})}
function showMarket(){if(state.combat)return;state.selected=state.current;activeTab='trade';save();render();document.querySelector('.tabs')?.scrollIntoView({behavior:'smooth',block:'start'})}

const $=s=>document.querySelector(s);
const escaped=x=>String(x).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const findPort=id=>PORTS.find(p=>p.id===id);
const findGood=id=>GOODS.find(g=>g.id===id);
const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
const rand=(min,max)=>Math.floor(Math.random()*(max-min+1))+min;
let state, qty='max',activeTab='trade',marketFilter='smart',toastTimer=null;
const seedNumber=s=>[...s].reduce((h,c)=>((h*31+c.charCodeAt(0))>>>0),73);
function marketInit(){const out={};for(const p of PORTS){out[p.id]={};for(const g of GOODS){const base=p.produces.includes(g.id)?153:p.needs.includes(g.id)?28:89;out[p.id][g.id]=clamp(base+(seedNumber(p.id+g.id)%43)-21,10,220)}}return out}
function newJob(portIndex,cycle,day){const p=PORTS[portIndex],target=PORTS[(portIndex+4+(cycle%5))%PORTS.length],good=p.produces[cycle%p.produces.length],count=12+(portIndex%4)*4,days=distanceDays(p,target,{speed:1.25,sails:0});return{id:p.id+'-'+cycle,from:p.id,to:target.id,good,qty:count,reward:Math.round(450+count*findGood(good).base*.86+days*80),deadline:day+27+days,availableAt:day};}
function initial(){const stocks=marketInit(),jobs={};PORTS.forEach((_,i)=>jobs[PORTS[i].id]=newJob(i,0,1));return{version:1,day:1,gold:5400,reputation:0,current:'havana',selected:'havana',cargo:{},stocks,ship:'sloop',hull:100,crew:18,upgrades:{hull:0,hold:0,sails:0,cannons:0},estates:{},jobs,activeContracts:[],jobCycle:{},log:[{day:1,text:T('startLog')}],combat:null,winCount:0};}
function load(){try{const raw=localStorage.getItem(SAVE_KEY);if(raw){const obj=JSON.parse(raw);if(obj.version===1&&obj.stocks&&obj.current&&obj.upgrades&&obj.cargo){state=obj;state.selected=findPort(state.selected)?state.selected:state.current;return}}}catch(e){console.warn('Сохранение повреждено; новая игра.',e)}state=initial();save()}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch(e){console.warn('Автосохранение недоступно:',e)}}
function log(message){state.log.unshift({day:state.day,text:message});state.log=state.log.slice(0,70)}
function popup(message){const el=$('#toast');el.textContent=message;el.classList.add('show');if(toastTimer)clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3100)}
function shipStats(){const base=SHIPS.find(s=>s.id===state.ship),u=state.upgrades;return{...base,capacity:base.capacity+u.hold*30,maxHull:base.hull+u.hull*24,guns:base.guns+u.cannons*4,speed:base.speed+u.sails*.09,crewMax:base.crew+u.hull*2}}
function loadQty(){return Object.values(state.cargo).reduce((a,b)=>a+b,0)}
function isHere(){return state.current===state.selected}
function price(portId,goodId,side){const p=findPort(portId),g=findGood(goodId),stock=state.stocks[portId][goodId],special=(p.produces.includes(goodId)?-.11:p.needs.includes(goodId)?.12:0),factor=clamp(1+(95-stock)/110*.7+special,.37,1.84),mid=g.base*factor;return side==='buy'?Math.ceil(mid*1.09):Math.floor(mid*.91)}
function distanceDays(a,b,ship){const length=Math.hypot(a.x-b.x,a.y-b.y),speed=ship.speed||1;return Math.max(1,Math.ceil(length/(105*speed)))}
function currentTravelDays(p){return distanceDays(findPort(state.current),p,shipStats())}
function stockGood(port,id){return state.stocks[port][id]}
function quantityFor(g,side){if(qty!=='max')return qty;return side==='buy'?Math.min(stockGood(state.current,g.id),shipStats().capacity-loadQty(),Math.floor(state.gold/price(state.current,g.id,'buy'))):state.cargo[g.id]||0}
function originalTrade(gid,side,forcedQty=null){if(!isHere()||state.combat){popup('Торговать можно только в порту, где стоит ваш корабль.');return}const g=findGood(gid);if(!g)return;const q=forcedQty===null?quantityFor(g,side):forcedQty;const have=state.cargo[gid]||0,p=price(state.current,gid,side),available=stockGood(state.current,gid),capacity=shipStats().capacity-loadQty();if(!Number.isInteger(q)||q<1){popup('Недостаточно денег, товара или места в трюме.');return}
if(side==='buy'){if(available<q||capacity<q||state.gold<q*p){popup('Не хватает монет, товара на рынке или места в трюме.');return}state.gold-=q*p;state.cargo[gid]=have+q;state.stocks[state.current][gid]-=q;log(`Куплено: ${g.name.toLowerCase()} ×${q} за ${money(q*p)} (${findPort(state.current).name}).`)}else{if(have<q){popup('В трюме недостаточно товара.');return}state.gold+=q*p;state.cargo[gid]=have-q;state.stocks[state.current][gid]+=q;log(`Продано: ${g.name.toLowerCase()} ×${q} за ${money(q*p)} (${findPort(state.current).name}).`)}save();render();popup(side==='buy'?'Товар загружен.':'Сделка завершена.')}
function dailySimulation(days){for(let d=0;d<days;d++){state.day++;for(const p of PORTS){for(const g of GOODS){const old=state.stocks[p.id][g.id];let shift=p.produces.includes(g.id)?rand(1,4):p.needs.includes(g.id)?-rand(1,3):rand(-2,2);state.stocks[p.id][g.id]=clamp(old+shift,7,245)}}for(const [id,est] of Object.entries(state.estates)){const g=findGood(est.good);if(g){est.stored=clamp(est.stored+2*est.level,0,150)}}if(state.day%3===0){const wages=Math.max(2,Math.ceil(state.crew/3));state.gold=Math.max(0,state.gold-wages)}for(let i=0;i<PORTS.length;i++){const port=PORTS[i];if(!state.jobs[port.id]){const cycle=(state.jobCycle[port.id]||0)+1;state.jobCycle[port.id]=cycle;state.jobs[port.id]=newJob(i,cycle,state.day)}}}const before=state.activeContracts.length;state.activeContracts=state.activeContracts.filter(c=>{if(state.day>c.deadline){state.reputation=Math.max(-30,state.reputation-2);log(`Контракт просрочен: ${findPort(c.to).name} (${findGood(c.good).name}).`);return false}return true});if(before!==state.activeContracts.length)popup('Один из контрактов просрочен.')}
function originalStartSail(){if(isHere()||state.combat)return;const from=findPort(state.current),to=findPort(state.selected),preview=routePreview(to.id);const days=preview.days;dailySimulation(days);log(`${portName(from.id)} → ${portName(to.id)} · ${days} ${dayUnit(days)}`);if(Math.random()<preview.risk){state.combat={from:from.id,to:to.id,days,enemy:{name:preview.enemy.name,type:preview.enemy.type,classId:preview.enemy.classId,hull:preview.enemy.hull,maxHull:preview.enemy.maxHull,crew:preview.enemy.crew,guns:preview.enemy.guns},round:1,predictedWin:preview.win,history:[T('piratesBlocked')],braced:false};log(T('piratesAhead'));save();render();return}arrive(to.id,days)}
function originalArrive(portId,days){state.current=portId;state.selected=portId;log(`Прибытие в ${findPort(portId).name}. В море: ${days} дн.`);state.combat=null;save();render();popup('Корабль вошёл в порт '+findPort(portId).name+'.')}
function originalFight(action){const battle=state.combat;if(!battle)return;const s=shipStats(),en=battle.enemy;const finishVictory=()=>{const bounty=enemyBounty(en)+battle.days*14;state.gold+=bounty;state.reputation+=4;state.winCount++;log(`${T('piratesDefeated')} ${money(bounty)}`);arrive(battle.to,battle.days);popup(`${T('piratesDefeated')} ${money(bounty)}`)};const finishDefeat=()=>{const lost=Math.floor(state.gold*.21);for(const g of GOODS){const n=state.cargo[g.id]||0;if(n)state.cargo[g.id]=Math.max(0,n-Math.ceil(n*.32))}state.gold=Math.max(0,state.gold-lost);state.hull=Math.ceil(s.maxHull*.38);state.crew=Math.max(5,Math.ceil(s.crewMax*.5));state.combat=null;state.current=battle.from;state.selected=battle.from;log(`${T('defeatTow')} ${money(lost)}`);save();render();popup(T('defeatTow'));};
if(action==='auto'){const chance=battle.round===1&&Number.isFinite(battle.predictedWin)?battle.predictedWin:combatWinEstimate(en);if(Math.random()<chance){battle.history.unshift(`${T('autobattle')}: ${pct(chance)}.`);finishVictory()}else{battle.history.unshift(`${T('autobattle')}: ${pct(chance)}.`);finishDefeat()}return}
let line='';if(action==='flee'){const chance=combatFleeChance(battle.round);if(Math.random()<chance){battle.history.unshift(T('routeContinued'));log(T('routeContinued'));arrive(battle.to,battle.days);return}line=T('fleeFailed')} else if(action==='cannon'){const dmg=Math.max(8,rand(9,16)+Math.ceil(s.guns*.28)-Math.floor(en.guns*.08));en.hull=Math.max(0,en.hull-dmg);line=`${T('cannon')}: -${dmg}`}
else if(action==='chain'){const dmg=Math.max(5,rand(5,11)+Math.ceil(s.guns*.18));const gunLoss=Math.max(1,Math.floor(dmg/6));en.hull=Math.max(0,en.hull-Math.floor(dmg*.55));en.guns=Math.max(1,en.guns-gunLoss);line=`${T('chain')}: -${gunLoss}`}
else if(action==='grape'){const crewLoss=Math.max(1,rand(2,6)+Math.floor(s.guns*.08));en.crew=Math.max(0,en.crew-crewLoss);line=`${T('grape')}: -${crewLoss}`}
else if(action==='board'){const attack=rand(8,18)+state.crew;const defend=rand(6,16)+en.crew;if(attack>=defend){const crewLoss=Math.max(3,rand(4,8));const hullLoss=Math.max(6,rand(6,13));en.crew=Math.max(0,en.crew-crewLoss);en.hull=Math.max(0,en.hull-hullLoss);state.crew=Math.max(4,state.crew-rand(1,3));line=`${T('board')}: ${crewLoss}`;}else{const ownLoss=rand(2,6);state.crew=Math.max(4,state.crew-ownLoss);state.hull=Math.max(1,state.hull-rand(5,12));line=`${T('board')}: -${ownLoss}`;}}
if(line)battle.history.unshift(line);if(en.hull<=0||en.crew<=0){finishVictory();return}const enemyDmg=Math.max(2,rand(4,10)+Math.ceil(en.guns*.27)-Math.floor(state.upgrades.hull*.5));state.hull=Math.max(0,state.hull-enemyDmg);if(Math.random()<.16)state.crew=Math.max(4,state.crew-1);battle.history.unshift(`${pirateName(en.type||'pirateBrig')}: -${enemyDmg}`);battle.round++;if(state.hull<=0){finishDefeat();return}save();render()}
function originalUpgrade(kind){if(state.combat||!isHere())return;const u=state.upgrades;const c={hull:650+u.hull*310,hold:1250+u.hold*700,sails:1050+u.sails*650,cannons:1350+u.cannons*790};if(!(kind in c)||u[kind]>=4)return;const cost=c[kind];if(state.gold<cost){popup('Недостаточно монет.');return}state.gold-=cost;u[kind]++;if(kind==='hull')state.hull+=24;log(`Верфь: улучшение «${{hull:'Корпус',hold:'Трюм',sails:'Паруса',cannons:'Орудия'}[kind]}» (${money(cost)}).`);save();render();popup('Корабль улучшен.')}
function repair(){const s=shipStats(),missing=s.maxHull-state.hull,cost=Math.ceil(missing*5);if(!isHere()||missing<=0)return;if(state.gold<cost){popup('Недостаточно монет для ремонта.');return}state.gold-=cost;state.hull=s.maxHull;log(`Корпус отремонтирован за ${money(cost)}.`);save();render();popup('Корпус восстановлен.')}
function recruit(){const s=shipStats(),count=Math.min(5,s.crewMax-state.crew),cost=count*38;if(!isHere()||count<=0)return;if(state.gold<cost){popup('Недостаточно монет.');return}state.gold-=cost;state.crew+=count;log(`Нанято ${count} матросов за ${money(cost)}.`);save();render();popup('Экипаж пополнен.')}
function originalBuyShip(id){if(!isHere()||state.combat)return;const next=SHIPS.find(s=>s.id===id),current=SHIPS.find(s=>s.id===state.ship);if(!next||next.id===current.id)return;const tradeIn=Math.floor(current.cost*.42)+(current.id==='sloop'?1000:0);const payable=Math.max(0,next.cost-tradeIn);if(state.gold<payable){popup('Не хватает золота на покупку корабля.');return}if(loadQty()>next.capacity){popup('Трюм нового корабля мал для вашего груза.');return}if(!window.confirm(`Купить ${next.name} за ${money(payable)} с учётом зачёта старого корабля? Улучшения старого судна не переносятся.`))return;state.gold-=payable;state.ship=next.id;state.upgrades={hull:0,hold:0,sails:0,cannons:0};state.hull=next.hull;state.crew=next.crew;log(`Куплен корабль «${next.name}» за ${money(payable)}.`);save();render();popup('Ваш новый корабль: '+next.name)}
function originalBuildEstate(){if(!isHere()||state.estates[state.current])return;const p=findPort(state.current),cost=estateCost(p);if(state.gold<cost){popup('Недостаточно монет для покупки земли.');return}state.gold-=cost;state.estates[p.id]={good:p.produces[0],level:1,stored:0};log(`В ${p.name} куплена земля и построено производство: ${findGood(p.produces[0]).name} (${money(cost)}).`);save();render();popup('Производство открыто.')}
function estateCost(p){return 5700+PORTS.indexOf(p)*270}
function originalImproveEstate(){if(!isHere())return;const e=state.estates[state.current];if(!e||e.level>=4)return;const cost=3200*e.level;if(state.gold<cost){popup('Недостаточно монет.');return}state.gold-=cost;e.level++;log(`Модернизировано производство в ${findPort(state.current).name}: уровень ${e.level}.`);save();render();popup('Производство улучшено.')}
function originalCollectEstate(){if(!isHere())return;const e=state.estates[state.current];if(!e||e.stored<1)return;const moved=Math.min(e.stored,shipStats().capacity-loadQty());if(moved<=0){popup('В трюме не осталось места.');return}state.cargo[e.good]=(state.cargo[e.good]||0)+moved;e.stored-=moved;log(`Получено ${moved} ед. продукции «${findGood(e.good).name}» с собственного предприятия.`);save();render();popup('Продукция загружена на корабль.')}
function acceptJob(){if(!isHere())return;const job=state.jobs[state.current];if(!job)return;if(state.activeContracts.length>=2){popup('Можно вести не более двух контрактов одновременно.');return}state.activeContracts.push(job);state.jobs[state.current]=null;log(`Принято поручение: доставить ${job.qty} ед. «${findGood(job.good).name}» в ${findPort(job.to).name} до дня ${job.deadline}.`);save();render();popup('Контракт принят.')}
function originalDeliverJob(id){const index=state.activeContracts.findIndex(c=>c.id===id);if(index<0)return;const job=state.activeContracts[index],have=state.cargo[job.good]||0;if(state.current!==job.to||have<job.qty||state.day>job.deadline){popup('Не выполнены условия доставки.');return}const repBonus=Number.isFinite(job.reputationBonus)?job.reputationBonus:5;state.cargo[job.good]-=job.qty;state.gold+=job.reward;state.reputation+=repBonus;state.activeContracts.splice(index,1);log(`Контракт выполнен в ${findPort(job.to).name}: +${money(job.reward)}, репутация +${repBonus}.`);save();render();popup('Контракт выполнен: '+money(job.reward))}
function waitDay(){if(!isHere()||state.combat)return;dailySimulation(1);log(`День ожидания в порту ${findPort(state.current).name}.`);save();render();popup('Наступил новый день.')}
function topOpportunities(){return opportunityDetails().slice(0,3)}
function renderMap(){
const current=findPort(state.current),selected=findPort(state.selected);
$('#portPicker').innerHTML=PORTS.map(p=>`<option value="${p.id}" ${p.id===state.selected?'selected':''}>${escaped(portName(p.id))} (${escaped(nationName(p.nation))})</option>`).join('');
const zones=PIRATE_ZONES.map(z=>`<g class="pirate-zone"><circle class="zone-wash" cx="${z.x}" cy="${z.y}" r="${z.r}"/><circle class="zone-ring" cx="${z.x}" cy="${z.y}" r="${z.r}"/></g>`).join('');
const route=selected.id===current.id?'':`<line class="route-halo" x1="${current.x}" y1="${current.y}" x2="${selected.x}" y2="${selected.y}"/><line class="route-line" x1="${current.x}" y1="${current.y}" x2="${selected.x}" y2="${selected.y}"/>`;
$('#routeLayer').innerHTML=zones+route;
$('#portLayer').innerHTML=PORTS.map(p=>{const isCurrent=p.id===state.current,isSelected=p.id===state.selected;return `<g class="port-group ${isCurrent?'current':''} ${isSelected?'selected':''}" data-port="${p.id}" tabindex="0" role="button" aria-label="${escaped(portName(p.id))}"><circle class="port-halo" cx="${p.x}" cy="${p.y}" r="13"/><circle class="main" cx="${p.x}" cy="${p.y}" r="6.5"/><title>${escaped(portName(p.id))}</title></g>`}).join('');
const busy=PORTS.map(p=>({x:p.x,y:p.y}));const occupied=[];
const ctx=document.createElement('canvas').getContext('2d');ctx.font='600 12px Arial, sans-serif';
const sorted=[...PORTS].sort((a,b)=>Number(b.id===state.current)-Number(a.id===state.current)||Number(b.id===state.selected)-Number(a.id===state.selected)||a.x-b.x);
const output=[];
for(const port of sorted){
 const name=portName(port.id),w=Math.min(180,Math.ceil(ctx.measureText(name).width)+20),h=23,x=port.x,y=port.y;
 const candidates=[
 {x:x+13,y:y-29},{x:x+13,y:y+12},{x:x-13-w,y:y-29},{x:x-13-w,y:y+12},
 {x:x-w/2,y:y-47},{x:x-w/2,y:y+22},{x:x+21,y:y-12},{x:x-21-w,y:y-12},
 {x:x+16,y:y-54},{x:x-16-w,y:y+32},{x:x+34,y:y+35},{x:x-34-w,y:y-55},
 {x:x+17,y:y+33},{x:x-17-w,y:y+33},{x:x-w/2,y:y-70},{x:x-w/2,y:y+50}];
 let best=null;
 for(const c of candidates){
   const rect={x:c.x,y:c.y,w,h};
   const out=Math.max(0,6-rect.x)+Math.max(0,rect.x+w-994)+Math.max(0,8-rect.y)+Math.max(0,rect.y+h-588);
   let overlap=0;
   for(const other of occupied){const dx=Math.max(0,Math.min(rect.x+w,other.x+other.w)-Math.max(rect.x,other.x));const dy=Math.max(0,Math.min(rect.y+h,other.y+other.h)-Math.max(rect.y,other.y));overlap+=dx*dy;}
   for(const spot of busy){if(spot.x===x&&spot.y===y)continue;const dx=Math.max(0,Math.abs(spot.x-(rect.x+w/2))-w/2-7);const dy=Math.max(0,Math.abs(spot.y-(rect.y+h/2))-h/2-7);if(dx===0&&dy===0)overlap+=180;}
   const lineDist=Math.hypot((rect.x+w/2)-x,(rect.y+h/2)-y);
   const score=out*400+overlap*30+lineDist*.23;
   if(best===null||score<best.score)best={...rect,score};
   if(score<18)break;
 }
 occupied.push(best);
 const nearX=Math.max(best.x,Math.min(x,best.x+w)),nearY=Math.max(best.y,Math.min(y,best.y+h));
 const cls=(port.id===state.current?' current-label':'')+(port.id===state.selected?' selected-label':'');
 output.push(`<g class="port-callout${cls}" data-port="${port.id}" tabindex="0" role="button" aria-label="${escaped(name)}"><path class="port-leader" d="M${x},${y}L${nearX},${nearY}"/><rect x="${best.x}" y="${best.y}" width="${w}" height="${h}" rx="5"/><text x="${best.x+10}" y="${best.y+15.7}">${escaped(name)}</text></g>`);
}
$('#labelLayer').innerHTML=output.join('');
}
function renderStats(){const s=shipStats();$('#stats').innerHTML=`<div class="stat"><div class="stat-label">${T('stats.gold')}</div><div class="stat-value gold">${money(state.gold)}</div></div><div class="stat"><div class="stat-label">${T('stats.day')}</div><div class="stat-value">${state.day}</div></div><div class="stat"><div class="stat-label">${T('stats.hold')}</div><div class="stat-value">${loadQty()}/${s.capacity}</div></div><div class="stat"><div class="stat-label">${T('stats.rep')}</div><div class="stat-value">${state.reputation>=0?'+':''}${state.reputation}</div></div>`;renderDockResources()}
