let careerFilter='next',careerRanksExpanded=false;
function ensureCareer(){if(state.career?.version===1){const c=state.career;c.counters||={};c.visited||={};c.ships||={};c.badges||={};c.victories||={};if(!Number.isInteger(c.rank)||c.rank<0)c.rank=0;return c}const c={version:1,rank:0,badges:{},victories:{},visited:{havana:1,[state.current]:1},ships:{sloop:1,[state.ship]:1},counters:{trades:0,bought:0,sold:0,revenue:0,voyages:0,seaDays:0,escapes:0,autoWins:0,boardings:0,estateUpgrades:0,collected:0,contracts:0,shipUpgrades:0}};state.career=c;return c}
function careerRecord(key,amount=1){const c=ensureCareer();c.counters[key]=Math.max(0,(Number(c.counters[key])||0)+amount)}
function careerWorth(){let value=state.gold;for(const [gid,qty] of Object.entries(state.cargo||{}))if(findGood(gid)&&qty>0)value+=price(state.current,gid,'sell')*qty;for(const [id,est] of Object.entries(state.estates||{})){const p=findPort(id);if(p)value+=Math.round(estateCost(p)*.8+3200*est.level*(est.level-1)*.2)}const ship=SHIPS.find(s=>s.id===state.ship);value+=(ship?.cost||1000)*.5;return Math.round(Math.max(0,value))}
function careerMetric(k){const c=ensureCareer();switch(k){case 'wins':return state.winCount||0;case 'reputation':return state.reputation||0;case 'gold':return state.gold||0;case 'worth':return careerWorth();case 'estates':return Object.keys(state.estates||{}).length;case 'visited':return Object.keys(c.visited||{}).length;case 'shipTypes':return Object.keys(c.ships||{}).length;case 'rank':return c.rank;default:return Math.max(0,c.counters[k]||0)}}
function metRequirements(req){return Object.entries(req).every(([key,value])=>careerMetric(key)>=value)}
function grantCareerProgress(){const c=ensureCareer();let changed=false;for(let pass=0;pass<24;pass++){let advanced=false;for(const a of AWARD_DEFS){if(!c.badges[a.id]&&careerMetric(a.metric)>=a.target){c.badges[a.id]=state.day;state.gold+=a.reward;state.reputation+=1;log(`${CT('rewardUnlocked')}: ${a.name[uiLang]} (+${money(a.reward)}, +1 ${CT('rewardRep')})`);advanced=true;changed=true}}if(c.rank<CAREER_RANKS.length-1&&metRequirements(CAREER_RANKS[c.rank+1].req)){c.rank++;const rank=CAREER_RANKS[c.rank];state.gold+=rank.bonus;state.reputation+=2;log(`${CT('rankUnlocked')}: ${rank.title[['ru','en','az'].indexOf(uiLang)]} (+${money(rank.bonus)}, +2 ${CT('rewardRep')})`);advanced=true;changed=true}for(const ending of CAREER_ENDINGS){if(!c.victories[ending.id]&&metRequirements(ending.req)){c.victories[ending.id]=state.day;state.gold+=ending.reward;log(`${CT('finalUnlocked')}: ${ending.title[uiLang]} (+${money(ending.reward)})`);advanced=true;changed=true}}if(!advanced)break}if(changed)save();return changed}
function recordVisit(id){if(findPort(id))ensureCareer().visited[id]=1}
function titleForRank(index){return CAREER_RANKS[index].title[['ru','en','az'].indexOf(uiLang)]}
function formatCareerValue(key,v){return ['gold','worth','revenue'].includes(key)?money(v):Math.floor(v).toLocaleString(LOCALES[uiLang]||'ru-RU')}
function requirementHtml(req){return Object.entries(req).map(([key,target])=>{const value=careerMetric(key),ok=value>=target,ratio=target?Math.min(100,100*value/target):100;return `<div class="career-requirement"><div class="career-req-top"><span>${escaped(CT('metric.'+key)||key)}</span><b class="${ok?'positive':''}">${formatCareerValue(key,value)} / ${formatCareerValue(key,target)} ${ok?'✓':''}</b></div><div class="meter"><div class="meter-inner" style="width:${ratio}%"></div></div></div>`}).join('')}
function endingCard(ending){const won=!!ensureCareer().victories[ending.id];return `<section class="ending-card ${won?'achieved':''}"><div class="ending-heading"><span class="ending-icon">${ending.icon}</span><div><b>${ending.title[uiLang]}</b><small>${won?CT('finished'):CT('pending')}</small></div></div>${requirementHtml(ending.req)}<div class="career-award">+${money(ending.reward)}</div></section>`}
function achievementCard(a){const c=ensureCareer(),done=!!c.badges[a.id],value=careerMetric(a.metric);return `<article class="achievement-item ${done?'unlocked':''}"><div class="achievement-icon">${done?'✓':'✦'}</div><div class="achievement-main"><div class="achievement-title">${a.name[uiLang]}</div><div class="achievement-detail">${CT('metric.'+a.metric)} · ${formatCareerValue(a.metric,Math.min(value,a.target))} / ${formatCareerValue(a.metric,a.target)}</div><div class="achievement-track"><span style="width:${Math.min(100,100*value/a.target)}%"></span></div></div><span class="achievement-reward">+${money(a.reward)}<small>+1 ${CT('rewardRep')}</small></span></article>`}
function renderCareer(){const c=ensureCareer(),rank=c.rank,next=CAREER_RANKS[rank+1],badges=Object.keys(c.badges).length;const endings=CAREER_ENDINGS.map(endingCard).join('');const rankView=(careerRanksExpanded?CAREER_RANKS:CAREER_RANKS.slice(0,Math.min(rank+3,CAREER_RANKS.length))).map((r,i)=>{const done=i<=rank,upcoming=i===rank+1;return `<div class="career-rank-row ${done?'done':''} ${upcoming?'upcoming':''}"><span class="rank-num">${String(i+1).padStart(2,'0')}</span><span>${r.title[['ru','en','az'].indexOf(uiLang)]}</span><span class="career-rank-state">${done?'✓':upcoming?'→':'·'}</span></div>`}).join('');let data=AWARD_DEFS;if(careerFilter==='next'){const unfinished=AWARD_DEFS.filter(a=>!c.badges[a.id]);data=unfinished.sort((a,b)=>{const ar=Math.min(1,careerMetric(a.metric)/a.target),br=Math.min(1,careerMetric(b.metric)/b.target);return br-ar||a.target-b.target}).slice(0,12)}else if(careerFilter==='won')data=AWARD_DEFS.filter(a=>c.badges[a.id]);else if(careerFilter!=='all')data=AWARD_DEFS.filter(a=>a.group===careerFilter);const filters=[['next',CT('showNext')],['all',CT('showAll')],['won',CT('showWon')],...Object.keys(CT('group')).map(g=>[g,CT('group.'+g)])];return `<div class="career-main"><div class="career-topline"><div><div class="eyebrow">${CT('kicker')}</div><h3>${CT('current')}: ${titleForRank(rank)}</h3><p class="muted small">${CT('achievements')}: <b>${badges}/${AWARD_DEFS.length}</b> · ${CT('rank')}: <b>${rank+1}/${CAREER_RANKS.length}</b></p></div><div class="career-emblem">${rank>=14?'♛':rank>=10?'♜':'✦'}</div></div><div class="career-progress"><div style="width:${100*(rank+1)/CAREER_RANKS.length}%"></div></div><section class="career-section"><h3>${next?CT('nextRank')+': '+titleForRank(rank+1):CT('finished')}</h3>${next?requirementHtml(next.req)+`<p class="career-award">${CT('rankBonus')}: +${money(next.bonus)} · +2 ${CT('rewardRep')}</p>`:`<p>${CT('campaignWon')}</p>`}</section><section class="career-section"><div class="career-heading"><h3>${CT('rankPath')}</h3><button class="career-filter" data-toggle-ranks>${careerRanksExpanded?CT('less'):CT('more')}</button></div><div class="career-ladder">${rankView}</div></section><section class="career-section"><h3>${CT('paths')}</h3><div class="endings-grid">${endings}</div>${Object.keys(c.victories).length?`<p class="career-win-note">${CT('continue')}</p>`:''}</section><section class="career-section"><div class="career-heading"><h3>${CT('badges')}: ${badges}/${AWARD_DEFS.length}</h3></div><p class="muted small">${CT('badgesHint')}</p><div class="career-filter-row">${filters.map(([id,label])=>`<button class="career-filter ${careerFilter===id?'selected':''}" data-career-filter="${id}">${label}</button>`).join('')}</div><div class="achievements-grid">${data.length?data.map(achievementCard).join(''):`<div class="empty">${CT('finished')}</div>`}</div></section><p class="muted tiny">${CT('newCareer')}</p></div>`}
function renderCareerStrip(){const el=$('#careerStrip');if(!el)return;const c=ensureCareer();el.innerHTML=`<div class="career-strip-label"><span>✦ ${titleForRank(c.rank)}</span><small>${Object.keys(c.badges).length}/${AWARD_DEFS.length} ${CT('badges').toLowerCase()}</small></div><button class="career-strip-action" data-open-career>${CT('tab')} ›</button>`}
// Wrappers record only successful state changes; original trade/combat/economy is preserved.
function trade(gid,side,forcedQty=null){const before=(state.cargo[gid]||0),gold=state.gold;originalTrade(gid,side,forcedQty);const after=(state.cargo[gid]||0),diff=after-before;if(side==='buy'&&diff>0){careerRecord('trades');careerRecord('bought',diff)}else if(side==='sell'&&diff<0){careerRecord('trades');careerRecord('sold',-diff);careerRecord('revenue',Math.max(0,state.gold-gold))}if(diff!==0){grantCareerProgress();save();render()}}
function startSail(){const beforeDay=state.day,from=state.current,to=state.selected;originalStartSail();if(state.day>beforeDay&&from!==to){careerRecord('voyages');careerRecord('seaDays',state.day-beforeDay);recordVisit(state.current);grantCareerProgress();save();render()}}
function fight(action){const b=state.combat?{from:state.combat.from,to:state.combat.to}:null,wins=state.winCount||0,hadCombat=!!state.combat;originalFight(action);if(!hadCombat)return;if(action==='board')careerRecord('boardings');if(state.winCount>wins){if(action==='auto')careerRecord('autoWins');recordVisit(state.current)}else if(action==='flee'&&!state.combat&&b&&state.current===b.to)careerRecord('escapes');if(action==='auto'||action==='board'||state.winCount>wins||action==='flee'){grantCareerProgress();save();render()}}
function buyShip(id){const old=state.ship;originalBuyShip(id);if(old!==state.ship){ensureCareer().ships[state.ship]=1;grantCareerProgress();save();render()}}
function improveEstate(){const id=state.current,lv=state.estates[id]?.level||0;originalImproveEstate();const diff=(state.estates[id]?.level||0)-lv;if(diff>0){careerRecord('estateUpgrades',diff);grantCareerProgress();save();render()}}
function collectEstate(){const id=state.current,good=state.estates[id]?.good,before=good?(state.cargo[good]||0):0;originalCollectEstate();const diff=good?(state.cargo[good]||0)-before:0;if(diff>0){careerRecord('collected',diff);grantCareerProgress();save();render()}}
function upgrade(kind){const before=state.upgrades[kind]||0;originalUpgrade(kind);if(state.upgrades[kind]>before){careerRecord('shipUpgrades');grantCareerProgress();save();render()}}
function deliverJob(id){const before=state.activeContracts.some(c=>c.id===id),r=state.reputation;originalDeliverJob(id);if(before&&!state.activeContracts.some(c=>c.id===id)&&state.reputation>r){careerRecord('contracts');grantCareerProgress();save();render()}}
function arrive(portId,days){originalArrive(portId,days);recordVisit(portId);grantCareerProgress();save();render()}
function buildEstate(){const before=Object.keys(state.estates).length;originalBuildEstate();if(Object.keys(state.estates).length>before){grantCareerProgress();save();render()}}

