const careerMetricOriginal=careerMetric;
careerMetric=function(k){const e=ensureEmpire();if(e){if(k==='autosold')return e.stats.autoSold;if(k==='buildings')return e.stats.buildings;if(k==='rivalsBought')return e.stats.rivalsBought;if(k==='chiefs')return e.stats.chiefs;if(k==='treasures')return e.stats.treasures;if(k==='industries')return PORTS.reduce((n,p)=>n+Object.keys(e.industries[p.id]||{}).length,0);if(k==='estates')return PORTS.filter(p=>Object.keys(e.industries[p.id]||{}).length>0).length;}return careerMetricOriginal(k)};
const careerWorthOriginal=careerWorth;
careerWorth=function(){const e=ensureEmpire();let subtotal=careerWorthOriginal();if(!e)return subtotal;for(const p of PORTS){for(const [g,ind] of Object.entries(e.industries[p.id]||{})){if(ind.legacy)continue;subtotal+=Math.round(industryValue(p.id,g,ind)*.68);subtotal+=Math.round(ind.stored*price(p.id,g,'sell')*.5)}}for(const p of PORTS)for(const [id,v] of Object.entries(e.projects[p.id]||{}))if(v){const pr=PROJECTS.find(x=>x.id===id);subtotal+=Math.round((pr?.cost||0)*.65)}return subtotal;};

const legacyDaily=dailySimulation;
dailySimulation=function(days){empireDaily(days)};
const legacyRender=render;
render=function(){ensureEmpire();legacyRender()};
const legacyRenderTab=renderTab;
renderTab=function(){if(activeTab==='adventure'){document.querySelectorAll('.tab').forEach(el=>{const a=el.dataset.tab==='adventure';el.classList.toggle('active',a);el.setAttribute('aria-selected',String(a))});$('#tabContent').innerHTML=empireAdventure();return}legacyRenderTab()};
const oldRenderChrome=renderChrome;
renderChrome=function(){oldRenderChrome();document.title='Caribbean Merchant v1.1';const tab=document.querySelector('[data-tab="adventure"]');if(tab)tab.textContent=ET('adventure');$('#footerLeft').textContent='Caribbean Merchant v1.1 · '+(uiLang==='ru'?'игровая стратегия':uiLang==='en'?'independent strategy':'müstəqil strategiya')};
renderTrade=empireTrade;
renderEstate=empireEstate;
renderContracts=empireContracts;
const legacyRenderDock=renderDock;
renderDock=function(){legacyRenderDock();const ready=state.activeContracts.filter(j=>j.to===state.current&&(state.cargo[j.good]||0)>=j.qty&&state.day<=j.deadline);if(ready.length&&isHere()){$('#routeInfo').insertAdjacentHTML('beforeend',`<div class="deliver-cta"><strong>${ET('missionReady')}: ${ready.map(j=>goodName(j.good)+' ×'+j.qty).join(', ')}</strong><button class="primary" data-empire-deliver>${ET('deliverNow')} · ${money(ready[0].reward)}</button></div>`)}};
const legacyRenderCombat=renderCombat;
renderCombat=function(){legacyRenderCombat();const b=state.combat;if(!b)return;const title=$('#modalHost .modal h2');if(title&&b.enemy){title.textContent=b.enemy.bossId?CHIEF_NAMES[PIRATE_ZONES.findIndex(z=>z.id===b.enemy.bossId)]?.[uiLang]||b.enemy.name:pirateClassName(b.enemy.classId)||b.enemy.name}};
const oldRoutePreview=routePreview;
routePreview=function(target){const v=oldRoutePreview(target),e=ensureEmpire();if(e){for(const z of v.zoneHits||[]){if(e.chiefs[z.zone.id]?.defeated)v.risk*=1-Math.min(.32,z.exposure*.33)}if(e.projects[state.current]?.fort||e.projects[target]?.fort)v.risk*=.84;v.risk=clamp(v.risk,0,.72)}return v};
const oldStartSail=startSail;
startSail=function(){const initialDay=state.day,from=state.current,to=state.selected;oldStartSail();const e=ensureEmpire();if(state.day>initialDay&&from!==to){if(!e.treasureClaimed&&e.treasureFragments<4&&Math.random()<.095){e.treasureFragments++;log(`${ET('pieces')}: ${e.treasureFragments}/4`)}if(state.combat){const preview=routePreview(to);const candidates=(preview.zoneHits||[]).filter(z=>!e.chiefs[z.zone.id].defeated);if(candidates.length&&Math.random()<.23){const z=candidates[0].zone,idx=PIRATE_ZONES.indexOf(z),b=state.combat;const boost=1+idx*.28;b.enemy.bossId=z.id;b.enemy.name=CHIEF_NAMES[idx][uiLang];b.enemy.hull=Math.round(b.enemy.hull*boost);b.enemy.maxHull=b.enemy.hull;b.enemy.crew=Math.round(b.enemy.crew*boost);b.enemy.guns=Math.round(b.enemy.guns*boost);b.predictedWin=combatWinEstimate(b.enemy);b.history.unshift(`${ET('pirateLeader')}: ${b.enemy.name}`)}}save();render()}};
const oldFight=fight;
fight=function(action){const before=state.combat?.enemy?{bossId:state.combat.enemy.bossId,from:state.combat.from,to:state.combat.to}:null;const wonBefore=state.winCount;oldFight(action);if(state.winCount>wonBefore){if(before?.bossId)finishChief(before.bossId);if(action==='board'){state.gold+=1200;log(`${ET('prize')}: ${money(1200)}`)}const e=ensureEmpire();if(!e.treasureClaimed&&e.treasureFragments<4&&Math.random()<.22){e.treasureFragments++;log(`${ET('pieces')}: ${e.treasureFragments}/4`)}grantCareerProgress();save();render()}};
const oldDeliverJob=deliverJob;
deliverJob=function(id){const job=state.activeContracts.find(j=>j.id===id),from=job?.from,to=job?.to,before=job?true:false;oldDeliverJob(id);if(before&&!state.activeContracts.some(j=>j.id===id)){const e=ensureEmpire();const nation=findPort(to).nation;e.nationRep[nation]=clamp(e.nationRep[nation]+3,-100,100);grantCareerProgress();save();render()}};
// Remove duplicate nation credit from the route's one-click delivery action.
deliverReady=function(){const c=state.activeContracts.find(j=>j.to===state.current&&(state.cargo[j.good]||0)>=j.qty&&state.day<=j.deadline);if(c)deliverJob(c.id)};
acceptJob=takeContract;
// Preserve single-ship trade-in: buyShip is intentionally unchanged.
// More intelligent enemy AI: raiders use hull shot; hunters aim at crew; bosses attempt boarding.
// Combat remains turn-based and always allows manual actions, escape and auto-resolve.
const originalFightBeforeAI=originalFight;
originalFight=function(action){if(!state.combat)return;const b=state.combat,e=b.enemy;const crewBefore=state.crew,oldHull=state.hull;originalFightBeforeAI(action);if(state.combat===b&&b.round>1){if(e.bossId&&Math.random()<.23)state.crew=Math.max(3,state.crew-2);else if(e.classId==='hunter'&&Math.random()<.20)state.crew=Math.max(3,state.crew-1);if(state.crew!==crewBefore)log(`${ET('pirates')}: ${ET('atSea')} -${crewBefore-state.crew}`);save();render()}};

function bindV1(){document.addEventListener('click',event=>{const x=event.target.closest('[data-build-industry],[data-build-all],[data-industry-upgrade],[data-warehouse-upgrade],[data-warehouse-all],[data-empire-collect],[data-empire-accept],[data-empire-deliver],[data-empire-section],[data-project],[data-capital],[data-rival-buyout],[data-hideout],[data-claim-treasure],[data-adventure-section],[data-contract-autoload]');if(!x)return;event.stopPropagation();event.preventDefault();if(x.disabled)return;if(x.dataset.buildIndustry)buildIndustry(x.dataset.buildIndustry);else if(x.hasAttribute('data-build-all'))buildAllIndustries();else if(x.dataset.industryUpgrade)levelIndustry(x.dataset.industryUpgrade);else if(x.dataset.warehouseUpgrade)expandWarehouse(x.dataset.warehouseUpgrade);else if(x.hasAttribute('data-warehouse-all'))expandAllWarehouses();else if(x.dataset.empireCollect)collectGoods(x.dataset.empireCollect);else if(x.hasAttribute('data-empire-accept'))takeContract();else if(x.hasAttribute('data-empire-deliver'))deliverReady();else if(x.dataset.empireSection){empireSection=x.dataset.empireSection;renderTab()}else if(x.dataset.project)buildProject(x.dataset.city,x.dataset.project);else if(x.dataset.capital)setCapital(x.dataset.capital);else if(x.dataset.rivalBuyout)buyoutRival(Number(x.dataset.rivalBuyout));else if(x.dataset.hideout)startHideout(x.dataset.hideout);else if(x.hasAttribute('data-claim-treasure'))claimTreasure();else if(x.dataset.adventureSection){adventureSection=x.dataset.adventureSection;renderTab();}else if(x.dataset.contractAutoload)refillContract(x.dataset.contractAutoload);},true);
document.addEventListener('change',event=>{const x=event.target.closest('[data-industry-setting]');if(x){configureIndustry(x.dataset.city,x.dataset.good,x.dataset.industrySetting,x.value)}});
document.addEventListener('keydown',event=>{if(event.key==='7'&&!event.ctrlKey&&!event.altKey&&!event.metaKey&&!['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)&&!state.combat){activeTab='adventure';renderTab()}})
}

const HELP_V1={
 ru:['Как играть — Caribbean Merchant v1.1','Торгуйте: в рынке видно товары на борту, рыночный остаток и запас собственного склада. «Макс.» рассчитывается по деньгам и месту в трюме. Цена меняется с объёмом сделки.','Предприятия: в любом городе можно построить все 10 товаров. Новые предприятия автоматически продают 75% продукции. Настройте резерв, минимальную цену и долю продаж 0/25/50/75/100%.','Склады: каждое производство хранит 150 единиц, расширение 200/250/300 стоит 2 500 / 3 500 / 4 000 кр. Есть массовые действия.','Контракты: «Принять» сначала проверит свободный трюм, товар на своём складе, остаток рынка и деньги. Только после полной проверки груз загрузится. По прибытии нажмите «Выполнить контракт».','Город: школы, гильдии, таможня, укрепления, губернаторская резиденция и личный дворец дают бонусы. Вкладка «Приключения» содержит пиратские убежища, конкурентов, державы и сокровища.','Карьера: 16 званий, более 80 достижений и три разных финала. Управляется один корабль, при покупке нового прежний сдаётся в зачёт.','Автосохранение действует в этом браузере. Перед заменой HTML-версии экспортируйте JSON; затем загрузите его в новой версии. Существующие партии сохраняются.'],
 en:['How to play — Caribbean Merchant v1.1','Trade: the market shows ship cargo, public stock and your private warehouse. Max buy checks funds and free hold. Prices adjust within large transactions.','Industries: all 10 goods can be produced in any town. New businesses auto-sell 75% of output. Configure reserve, minimum sale price and 0/25/50/75/100% sale share.','Warehouses: each business begins with capacity 150. Upgrades to 200/250/300 cost 2,500 / 3,500 / 4,000 cr. Bulk actions are available.','Contracts: Accept checks cargo space, private stock, market supply and funds, then loads the entire order atomically. On arrival press Complete contract.','Cities: schools, trade guilds, customs houses, defenses, governor residences and a palace offer bonuses. Adventures includes pirate hideouts, rivals, nations and treasure.','Career: 16 ranks, over 80 achievements and three endings. One ship is controlled, with a trade-in discount for the previous ship.','Your game is saved automatically in this browser. Export JSON before switching HTML versions and import it into the new version. Existing progress is preserved.'],
 az:['Necə oynamaq olar — Caribbean Merchant v1.1','Ticarət: bazarda gəmidəki yük, ümumi bazar ehtiyatı və şəxsi anbar görünür. Maksimum alış pul və boş yeri nəzərə alır. Böyük partiyalarda qiymət dəyişir.','İstehsal: hər şəhərdə 10 malın hamısı istehsal oluna bilər. Yeni müəssisələr məhsulun 75%-ni avtomatik satır. Ehtiyatı, minimal qiyməti və 0/25/50/75/100% satışı tənzimləyin.','Anbarlar: hər müəssisə 150 tutumla başlayır. 200/250/300 artımları 2 500 / 3 500 / 4 000 kr tutur. Kütləvi əməliyyatlar var.','Kontraktlar: Qəbul et düyməsi yük yerini, şəxsi anbarı, bazarı və pulu yoxlayır; bütün yükü bir əməliyyatla yükləyir. Gəldikdə kontraktı tamamlayın.','Şəhərlər: məktəb, gildiya, gömrük, istehkam, qubernator iqamətgahı və saray üstünlüklər verir. Macəralarda pirat sığınacaqları, rəqiblər, dövlətlər və xəzinə var.','Karyera: 16 rütbə, 80-dən çox nailiyyət və üç final. Yalnız bir gəmi idarə olunur; köhnə gəmi yenisinin qiymətinə hesablanır.','Oyun bu brauzerdə avtomatik saxlanır. HTML versiyasını dəyişməzdən əvvəl JSON faylını ixrac edin, sonra yeni versiyaya idxal edin.']};
help=function(){const lines=HELP_V1[uiLang]||HELP_V1.ru;$('#modalHost').innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-label="${T('help')}"><div class="eyebrow">${T('rules')}</div><h2>${lines[0]}</h2>${lines.slice(1).map((l,i)=>`<p><strong>${i+1}.</strong> ${l}</p>`).join('')}<div class="modal-actions"><button class="button" data-action="exportSave">${T('exportSave')}<small>${T('exportD')}</small></button><button class="button" data-action="importSave">${T('importSave')}<small>${T('importD')}</small></button></div><button class="primary modal-wide-btn" data-action="closeHelp">${T('continue')}</button></div>`};
const renderShipOriginal=renderShip;
renderShip=function(){return renderShipOriginal()+`<p class="fineprint">${ET('shipOnly')}</p>`};
// Additive diagnostic functions; no production mutation API is exposed.
const v1Diagnostics=()=>({industries:careerMetric('industries'),autoSold:ensureEmpire().stats.autoSold,revenue:ensureEmpire().stats.autoRevenue,buildings:careerMetric('buildings'),rivalsBought:careerMetric('rivalsBought'),chiefs:careerMetric('chiefs'),treasureFragments:ensureEmpire().treasureFragments,nations:structuredClone(ensureEmpire().nationRep)});

// Original-inspired supply/price elasticity: prices evolve *during* each batch trade.
function marketUnitPrice(pid,gid,side,unitsInMarket){const p=findPort(pid),g=findGood(gid);const special=p.produces.includes(gid)?-.11:p.needs.includes(gid)?.12:0;const factor=clamp(1+(95-unitsInMarket)/110*.7+special,.37,1.84),mid=g.base*factor;return side==='buy'?Math.ceil(mid*1.09):Math.floor(mid*.91)}
function marketQuote(pid,gid,side,n){if(!findPort(pid)||!findGood(gid)||!Number.isInteger(n)||n<0)return null;const stock=state.stocks[pid][gid];if((side==='buy'&&stock<n)||(side==='sell'&&stock+n>245))return null;let total=0;for(let i=0;i<n;i++){const s=side==='buy'?stock-i:stock+i;total+=marketUnitPrice(pid,gid,side,s)}return{quantity:n,total,average:n?total/n:0}}
maxBuyable=function(gid){if(state.combat||!findGood(gid))return 0;const n=Math.max(0,Math.min(state.stocks[state.current][gid],shipStats().capacity-loadQty()));let total=0,stock=state.stocks[state.current][gid],q=0;for(let i=0;i<n;i++){const unit=marketUnitPrice(state.current,gid,'buy',stock-i);if(total+unit>state.gold)break;total+=unit;q++}return q};
quantityFor=function(g,side){if(qty!=='max')return qty;return side==='buy'?maxBuyable(g.id):Math.min(state.cargo[g.id]||0,245-state.stocks[state.current][g.id])};
trade=function(gid,side,forcedQty=null){if(!isHere()||state.combat)return empireError(T('tradeData'));if(!findGood(gid)||!['buy','sell'].includes(side))return;let n=forcedQty===null?quantityFor(findGood(gid),side):Number(forcedQty);if(forcedQty===null&&qty==='max'&&side==='buy')n=maxBuyable(gid);if(forcedQty===null&&qty==='max'&&side==='sell')n=Math.min(state.cargo[gid]||0,245-state.stocks[state.current][gid]);if(!Number.isInteger(n)||n<1)return empireError(side==='buy'?`${ET('noGold')} / ${ET('noSpace')}`:ET('noOwn'));if(side==='buy'&&n>Math.max(0,shipStats().capacity-loadQty()))return empireError(ET('noSpace'));if(side==='sell'&&n>(state.cargo[gid]||0))return empireError(ET('noOwn'));const quote=marketQuote(state.current,gid,side,n);if(!quote)return empireError(ET('noGoods'));if(side==='buy'&&state.gold<quote.total)return empireError(`${ET('noGold')}: ${money(quote.total-state.gold)}`);
if(side==='buy'){state.gold-=quote.total;state.stocks[state.current][gid]-=n;state.cargo[gid]=(state.cargo[gid]||0)+n;careerRecord('bought',n);}else{state.gold+=quote.total;state.stocks[state.current][gid]+=n;state.cargo[gid]=(state.cargo[gid]||0)-n;careerRecord('sold',n);careerRecord('revenue',quote.total);if(findPort(state.current).needs.includes(gid)&&n>=15){state.reputation+=1;const nation=findPort(state.current).nation;ensureEmpire().nationRep[nation]=clamp(ensureEmpire().nationRep[nation]+1,-100,100)}}careerRecord('trades');empireCommit(`${side==='buy'?ET('buying'):T('sell')}: ${goodName(gid)} ×${n} · ${money(quote.total)}`)};
opportunityDetails=function(){const origin=findPort(state.current),out=[];for(const g of GOODS){const affordable=maxBuyable(g.id);if(affordable<1)continue;let best=null;for(const p of PORTS){if(p.id===origin.id)continue;const volume=Math.min(affordable,Math.max(0,245-state.stocks[p.id][g.id]));if(volume<1)continue;const fromQuote=marketQuote(origin.id,g.id,'buy',volume),toQuote=marketQuote(p.id,g.id,'sell',volume);if(!fromQuote||!toQuote)continue;const gross=toQuote.total-fromQuote.total;if(gross<=0)continue;const days=distanceDays(origin,p,shipStats()),score=gross/(days+1);if(!best||score>best.score)best={p,g,margin:Math.round(gross/volume),buy:Math.round(fromQuote.average),sell:Math.round(toQuote.average),days,volume,gross,score}}if(best)out.push(best)}return out.sort((a,b)=>b.score-a.score)};
// Reconcile displayed availability with the progressive batch quote and demand capacity.
const takeContractOld=takeContract;
takeContract=function(){if(!isHere()||state.combat)return;const job=state.jobs[state.current];if(!job)return;if(state.activeContracts.length>=2)return empireError('2 / 2');const aboard=state.cargo[job.good]||0,missing=Math.max(0,job.qty-aboard),own=Math.min(missing,ownStore(state.current,job.good)),marketNeed=missing-own;const free=shipStats().capacity-loadQty();if(free<missing)return empireError(`${ET('contractFailed')}: ${ET('contractRoom')} — ${missing-free} ${ET('units')}`);if(state.stocks[state.current][job.good]<marketNeed)return empireError(`${ET('contractFailed')}: ${ET('contractStock')} — ${ET('need')} ${marketNeed}, ${ET('marketStock')} ${state.stocks[state.current][job.good]}`);const quote=marketQuote(state.current,job.good,'buy',marketNeed);const cost=quote?.total;if(!Number.isFinite(cost))return empireError(ET('contractFailed'));if(state.gold<cost)return empireError(`${ET('contractFailed')}: ${ET('contractNeed')} ${money(cost-state.gold)}`);
// Exact atomic settlement: no partial cargo movement and no phantom purchases.
if(own)ownedIndustry(state.current,job.good).stored-=own;if(marketNeed){state.stocks[state.current][job.good]-=marketNeed;state.gold-=cost;careerRecord('bought',marketNeed)}state.cargo[job.good]=aboard+missing;state.activeContracts.push(job);state.jobs[state.current]=null;empireCommit(`${ET('contractBought')}: ${goodName(job.good)} ×${job.qty} → ${portName(job.to)} (${money(cost)})`);popup(ET('contractBought'));};
acceptJob=takeContract;
const empireContractsFlatQuote=renderContracts;
renderContracts=function(){let html=empireContractsFlatQuote();const job=state.jobs[state.selected];if(job){const aboard=state.cargo[job.good]||0,needed=Math.max(0,job.qty-aboard),own=Math.min(needed,ownStore(state.selected,job.good)),purch=needed-own;const exact=marketQuote(state.selected,job.good,'buy',purch)?.total;const approximated=purch*price(state.selected,job.good,'buy');html=html.replace(`${ET('buying')}: ${purch} × ${price(state.selected,job.good,'buy')} = <b>${money(approximated)}</b>`,`${ET('buying')}: ${purch} ${ET('units')} = <b>${exact===undefined?ET('noGoods'):money(exact)}</b>`);}return html};

// V1.1: save-compatible rotating offers and global production controls.
const baseJobGenerator=newJob;
newJob=function(portIndex,cycle,day){
 const job=baseJobGenerator(portIndex,cycle,day);
 const featured=cycle>0&&(portIndex+cycle)%4===0;
 job.featured=featured;
 job.reputationBonus=featured?8:5;
 if(featured)job.reward=Math.round(job.reward*1.5);
 return job;
};
function refreshAvailableJobs(){
 if(!state||!state.jobs)return false;
 state.jobCycle||={};
 let changed=false;
 for(let i=0;i<PORTS.length;i++){
  const pid=PORTS[i].id,job=state.jobs[pid];
  // Keep an accepted port's slot empty until the next simulated day; no same-day mission farming.
  if(!job)continue;
  if(job&&Number.isFinite(job.deadline)&&Number.isFinite(job.availableAt)&&job.deadline>=state.day&&job.availableAt<=state.day&&state.day-job.availableAt<7)continue;
  const idCycle=Number(String(job?.id||'').split('-').pop());
  const next=Math.max(Number(state.jobCycle[pid])||0,Number.isInteger(idCycle)?idCycle:0)+1;
  state.jobCycle[pid]=next;
  const fresh=newJob(i,next,state.day);
  if(ensureEmpire().projects[pid]?.governor){fresh.reward=Math.ceil(fresh.reward*1.18);fresh.deadline+=3;}
  state.jobs[pid]=fresh;
  changed=true;
 }
 return changed;
}
function setEmpireAutoSale(percent){
 if(![0,75,100].includes(percent))return;
 const e=ensureEmpire();
 const industries=Object.values(e.industries).flatMap(byGood=>Object.values(byGood));
 if(!industries.length)return empireError(ET('noOwn'));
 for(const factory of industries)factory.autoPct=percent;
 e.globalAutoPct=percent;
 empireCommit(`${ET('bulkUpdated')}: ${percent}% · ${industries.length}`);
}
const estateWithoutBulkControls=renderEstate;
renderEstate=function(){
 const html=estateWithoutBulkControls();
 if(empireSection!=='factories')return html;
 const e=ensureEmpire(),count=Object.values(e.industries).reduce((n,byGood)=>n+Object.keys(byGood).length,0);
 const buttons=[0,75,100].map(p=>`<button class="${e.globalAutoPct===p?'primary':'button'}" data-bulk-auto-pct="${p}" ${!count?'disabled':''}>${p}%</button>`).join('');
 const panel=`<div class="notice"><strong>${ET('bulkGlobal')}</strong><p class="muted small">${ET('bulkHint')}</p><div class="task-actions">${buttons}</div></div>`;
 return html.replace('</div>','</div>'+panel);
};
document.addEventListener('click',event=>{
 const button=event.target.closest('[data-bulk-auto-pct]');
 if(!button||button.disabled)return;
 event.preventDefault();event.stopPropagation();
 setEmpireAutoSale(Number(button.dataset.bulkAutoPct));
},true);

